/* Licensed Vendors Database — keyword search + left filter rail.
 *
 * Adapted from the admissions-design programs explorer
 * (admissions-design/pages/academics/programs.html): same rail, accordion
 * groups, "Show all" toggle, active-filter pills and mobile toggle, with the
 * keyword search moved INTO the rail and the results rendered as
 * umd-element-person list cards.
 *
 * Data comes from scripts/licensed-vendors-data.js (generated by
 * tools/build-vendor-data.py). Product categories never appear on a card —
 * they only drive the filter and the keyword search.
 *
 * Results are rebuilt from data on every change and never re-inserted:
 * umd-element-person re-renders additively when it reconnects, so moving an
 * existing card draws it twice (page-builder LAYOUT-PATTERNS.md "Filtered or
 * paginated grids").
 *
 * The initial keyword comes from the search input's value attribute or a
 * ?q= parameter, so a page can ship pre-searched.
 */
(function () {
  var VENDORS = window.UMD_BRAND_SITE_VENDORS || [];
  var BUCKETS = window.UMD_BRAND_SITE_VENDOR_BUCKETS || [];

  // Everyday words a buyer types, mapped to the bucket they mean. A keyword
  // that hits one of these matches every vendor in the bucket — "tshirt" finds
  // all Apparel vendors, not only the ones tagged Men's/Unisex T-shirts.
  // Placeholder vocabulary: confirm with Trademarks & Licensing.
  var KEYWORDS = {
    'Apparel': ['apparel', 'clothing', 'clothes', 'tshirt', 'tee', 'shirt', 'polo',
      'hoodie', 'sweatshirt', 'sweater', 'fleece', 'jacket', 'hat', 'cap', 'beanie',
      'shoe', 'sock', 'onesie', 'pajama', 'shorts', 'pants'],
    'Team & Athletic': ['athletic', 'sport', 'ball', 'jersey', 'uniform', 'golf', 'hockey'],
    'Jewelry & Accessories': ['jewelry', 'ring', 'necklace', 'bracelet', 'bag', 'tote',
      'backpack', 'lanyard', 'keychain', 'umbrella', 'scarf'],
    'Home & Housewares': ['home', 'mug', 'cup', 'tumbler', 'bottle', 'glass', 'blanket',
      'pillow', 'towel', 'chair', 'ornament'],
    'Toys, Games & Kids': ['toy', 'game', 'plush', 'puzzle', 'kid', 'baby'],
    'Gifts & Collectibles': ['gift', 'novelty', 'collectible', 'souvenir'],
    'Office, School & Print': ['office', 'pen', 'pencil', 'notebook', 'journal', 'paper',
      'sticker', 'decal', 'banner', 'sign', 'poster', 'book', 'folder'],
    'Health & Consumables': ['food', 'candy', 'snack', 'drink', 'beauty', 'lip balm',
      'sunscreen', 'mask', 'sanitizer'],
    'Electronics & Auto': ['electronic', 'tech', 'phone', 'charger', 'usb', 'speaker',
      'car', 'auto', 'license plate'],
    'Licensing': ['royalty', 'royalties', 'premium']
  };

  var SHOW_LIMIT = 7;

  var form = document.getElementById('umd-brand-site-filter-form');
  var qInput = document.getElementById('umd-brand-site-filter-keyword');
  var groupsHost = document.getElementById('umd-brand-site-filter-groups');
  var listHost = document.getElementById('umd-brand-site-filter-list');
  var emptyEl = document.getElementById('umd-brand-site-filter-empty');
  var countEl = document.getElementById('umd-brand-site-filter-count');
  var pillsHost = document.getElementById('umd-brand-site-filter-pills');
  var mobileToggle = document.getElementById('umd-brand-site-filter-mobile-toggle');

  var state = { q: '', category: [], vendor: [], fundraiser: [] };

  function esc(s) {
    return String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;')
      .replace(/>/g, '&gt;').replace(/"/g, '&quot;');
  }
  // "T-shirts", "t shirt", "tshirts" all compare as "tshirt"
  function norm(s) {
    return String(s).toLowerCase().replace(/[^a-z0-9]+/g, '').replace(/s$/, '');
  }
  function slug(s) { return String(s).toLowerCase().replace(/[^a-z0-9]+/g, '-'); }

  VENDORS.forEach(function (v) {
    v.haystack = norm([v.name, v.contact, v.address, v.website, v.email]
      .concat(v.categories).join(' '));
  });

  function countWith(test) {
    return VENDORS.filter(test).length;
  }
  function hasAny(v, cats) {
    return v.categories.some(function (c) { return cats.indexOf(c) > -1; });
  }

  // ---- filter rail -------------------------------------------------------
  // extraClass lands on the <label>; nested categories pass umd-sans-small
  function checkbox(group, value, label, count, extraClass, attrs) {
    return '<label class="umd-field-checkbox-wrapper' + (extraClass ? ' ' + extraClass : '') + '">' +
      '<input type="checkbox" data-group="' + group + '" value="' + esc(value) + '"' + (attrs || '') + '>' +
      '<span>' + esc(label) + (count === null ? '' :
      ' <span class="umd-brand-site-filter-count umd-sans-smaller">(' + count + ')</span>') + '</span></label>';
  }

  function group(key, title, open, body) {
    return '<div class="umd-brand-site-filter-group"' + (open ? ' data-open' : '') + ' data-group="' + key + '">' +
      '<button type="button" aria-expanded="' + open + '" aria-controls="umd-brand-site-filter-body-' + key + '">' +
      '<span>' + title + '</span></button>' +
      '<div class="umd-brand-site-filter-group-body" id="umd-brand-site-filter-body-' + key + '"><div>' +
      body + '</div></div></div>';
  }

  function categoryGroup() {
    return '<fieldset><legend class="sr-only">Product categories</legend>' +
      BUCKETS.map(function (b) {
        var id = 'umd-brand-site-filter-bucket-' + slug(b.title);
        var children = b.categories.map(function (c) {
          return checkbox('category', c, c, countWith(function (v) {
            return v.categories.indexOf(c) > -1;
          }), 'umd-sans-small', ' data-bucket="' + esc(b.title) + '"');
        }).join('');
        return '<div class="umd-brand-site-filter-bucket">' +
          '<div class="umd-brand-site-filter-bucket-row">' +
          checkbox('bucket', b.title, b.title, countWith(function (v) { return hasAny(v, b.categories); })) +
          '<button type="button" class="umd-brand-site-filter-bucket-toggle" aria-expanded="false" aria-controls="' + id + '">' +
          '<span class="sr-only">Show ' + esc(b.title) + ' categories</span></button></div>' +
          '<div class="umd-brand-site-filter-bucket-children" id="' + id + '" hidden>' + children + '</div></div>';
      }).join('') + '</fieldset>';
  }

  function vendorGroup() {
    var rows = VENDORS.map(function (v, i) {
      return checkbox('vendor', v.name, v.name, null,
        i >= SHOW_LIMIT ? 'umd-brand-site-filter-option-extra' : '');
    }).join('');
    return '<div class="umd-brand-site-filter-group-find">' +
      '<label class="sr-only" for="umd-brand-site-filter-vendor-find">Find a vendor name</label>' +
      '<input type="text" class="umd-field-input" id="umd-brand-site-filter-vendor-find" placeholder="Find a vendor name" autocomplete="off"></div>' +
      '<fieldset id="umd-brand-site-filter-set-vendor" data-collapsed><legend class="sr-only">Vendor name</legend>' +
      rows + '</fieldset>' +
      '<span class="umd-text-cluster-pill umd-brand-site-filter-show-all-cluster">' +
      '<button type="button" class="umd-brand-site-filter-show-all" aria-expanded="false" aria-controls="umd-brand-site-filter-set-vendor">' +
      'Show all ' + VENDORS.length + '</button></span>';
  }

  function fundraiserGroup() {
    return '<fieldset><legend class="sr-only">Internal fundraiser</legend>' +
      checkbox('fundraiser', 'yes', 'Approved for internal fundraisers',
        countWith(function (v) { return v.fundraiser; })) +
      '</fieldset>';
  }

  function buildGroups() {
    groupsHost.innerHTML =
      group('category', 'Product Categories', true, categoryGroup()) +
      group('vendor', 'Vendor Name', false, vendorGroup()) +
      group('fundraiser', 'Internal Fundraiser', false, fundraiserGroup());
  }

  // parent bucket box mirrors its children: all → checked, some → indeterminate
  function syncBuckets() {
    groupsHost.querySelectorAll('input[data-group="bucket"]').forEach(function (parent) {
      var kids = groupsHost.querySelectorAll('input[data-bucket="' + parent.value.replace(/"/g, '\\"') + '"]');
      var on = Array.prototype.filter.call(kids, function (k) { return k.checked; }).length;
      parent.checked = on === kids.length;
      parent.indeterminate = on > 0 && on < kids.length;
    });
  }

  // ---- matching ----------------------------------------------------------
  function keywordBuckets(q) {
    var n = norm(q);
    return BUCKETS.filter(function (b) {
      return norm(b.title) === n || (KEYWORDS[b.title] || []).some(function (w) {
        var k = norm(w);
        return n === k || (n.length > 3 && (n.indexOf(k) === 0 || k.indexOf(n) === 0));
      });
    });
  }

  function collect() {
    state.q = qInput.value.trim();
    state.category = []; state.vendor = []; state.fundraiser = [];
    form.querySelectorAll('input[type="checkbox"]:checked').forEach(function (cb) {
      var g = cb.getAttribute('data-group');
      if (state[g]) state[g].push(cb.value);
    });
  }

  // AND across groups, OR within a group
  function match(v, qBuckets) {
    if (state.q) {
      var n = norm(state.q);
      var inBucket = qBuckets.some(function (b) { return hasAny(v, b.categories); });
      if (!inBucket && v.haystack.indexOf(n) === -1) return false;
    }
    if (state.category.length && !hasAny(v, state.category)) return false;
    if (state.vendor.length && state.vendor.indexOf(v.name) === -1) return false;
    if (state.fundraiser.length && !v.fundraiser) return false;
    return true;
  }

  // ---- results -----------------------------------------------------------
  // The DS tabular person card, unaltered: led by the contact person, with the
  // vendor as their association. No wrapper classes — the card draws its own rules.
  // The vendor website is the card's link, in slot="actions" (rendered under
  // the person details). Fundraiser status uses the card's italic line
  // (slot="pronouns"); slot="additional-contact" is never rendered as of
  // components 2.0.0.
  function cardHTML(v) {
    return '<umd-element-person data-display="tabular">' +
      '<p slot="name">' + esc(v.contact || v.name) + '</p>' +
      '<p slot="association">' + esc(v.name) + '</p>' +
      (v.fundraiser ? '<p slot="pronouns">Approved for internal fundraisers</p>' : '') +
      (v.phone ? '<a slot="phone" href="tel:' + esc(v.tel) + '">' + esc(v.phone) + '</a>' : '') +
      (v.email ? '<a slot="email" href="mailto:' + esc(v.email) + '">' + esc(v.email) + '</a>' : '') +
      (v.address ? '<p slot="address">' + esc(v.address) + '</p>' : '') +
      (v.url ? '<div slot="actions"><umd-element-call-to-action data-display="secondary">' +
        '<a href="' + esc(v.url) + '" target="_blank" rel="noopener noreferrer">' +
        esc(v.website) + '<span class="sr-only"> (opens in a new tab)</span></a>' +
        '</umd-element-call-to-action></div>' : '') +
      '</umd-element-person>';
  }

  function render() {
    var qBuckets = state.q ? keywordBuckets(state.q) : [];
    var matched = VENDORS.filter(function (v) { return match(v, qBuckets); });

    listHost.replaceChildren();
    var holder = document.createElement('div');            // detached: no upgrade until appended
    holder.innerHTML = matched.map(cardHTML).join('');
    while (holder.firstElementChild) listHost.appendChild(holder.firstElementChild);
    emptyEl.hidden = matched.length > 0;

    var noun = matched.length === 1 ? ' licensed vendor' : ' licensed vendors';
    countEl.textContent = 'Showing ' + matched.length + noun;
    renderPills();
  }

  function renderPills() {
    var items = [];
    if (state.q) items.push({ k: 'q', v: '', label: '“' + state.q + '”' });
    state.category.forEach(function (c) { items.push({ k: 'category', v: c, label: c }); });
    state.vendor.forEach(function (c) { items.push({ k: 'vendor', v: c, label: c }); });
    if (state.fundraiser.length) items.push({ k: 'fundraiser', v: 'yes', label: 'Internal fundraiser' });
    if (!items.length) { pillsHost.hidden = true; pillsHost.innerHTML = ''; return; }
    pillsHost.hidden = false;
    pillsHost.innerHTML = '<span class="umd-brand-site-filter-pills-label">Filtered by:</span>' +
      '<span class="umd-text-cluster-pill umd-brand-site-filter-pill-cluster">' +
      items.map(function (it) {
        return '<button type="button" class="umd-brand-site-filter-pill" data-k="' + it.k + '" data-v="' +
          esc(it.v) + '"><span>' + esc(it.label) +
          ' <span aria-hidden="true">×</span><span class="sr-only"> (remove)</span></span></button>';
      }).join('') + '</span>' +
      '<button type="button" class="umd-brand-site-filter-clear umd-sans-min" data-clear-all>Clear all</button>';
  }

  function update() { collect(); render(); }

  function clearAll() {
    form.querySelectorAll('input[type="checkbox"]').forEach(function (cb) {
      cb.checked = false; cb.indeterminate = false;
    });
    qInput.value = '';
    update();
  }

  // ---- events ------------------------------------------------------------
  var debounce;
  qInput.addEventListener('input', function () {
    clearTimeout(debounce);
    debounce = setTimeout(update, 200);
  });
  form.addEventListener('submit', function (e) { e.preventDefault(); update(); });

  form.addEventListener('change', function (e) {
    var cb = e.target;
    if (!cb.matches('input[type="checkbox"]')) return;
    if (cb.getAttribute('data-group') === 'bucket') {
      groupsHost.querySelectorAll('input[data-bucket="' + cb.value.replace(/"/g, '\\"') + '"]')
        .forEach(function (k) { k.checked = cb.checked; });
    }
    syncBuckets();
    update();
  });

  groupsHost.addEventListener('click', function (e) {
    var more = e.target.closest('.umd-brand-site-filter-show-all');
    if (more) {
      var set = document.getElementById(more.getAttribute('aria-controls'));
      var collapsed = set.toggleAttribute('data-collapsed');
      more.setAttribute('aria-expanded', String(!collapsed));
      more.textContent = collapsed ? 'Show all ' + VENDORS.length : 'Show less';
      return;
    }
    var expand = e.target.closest('.umd-brand-site-filter-bucket-toggle');
    if (expand) {
      var kids = document.getElementById(expand.getAttribute('aria-controls'));
      kids.hidden = !kids.hidden;
      expand.setAttribute('aria-expanded', String(!kids.hidden));
      return;
    }
    var btn = e.target.closest('.umd-brand-site-filter-group > button');
    if (btn) {
      var open = btn.parentElement.toggleAttribute('data-open');
      btn.setAttribute('aria-expanded', open);
    }
  });

  // type-ahead inside the Vendor Name group: narrows the checkbox list only
  groupsHost.addEventListener('input', function (e) {
    if (e.target.id !== 'umd-brand-site-filter-vendor-find') return;
    var n = norm(e.target.value);
    var set = document.getElementById('umd-brand-site-filter-set-vendor');
    set.toggleAttribute('data-finding', !!n);
    set.querySelectorAll('label').forEach(function (l) {
      l.hidden = !!n && norm(l.textContent).indexOf(n) === -1;
    });
  });

  // "Reset filters" is a umd-element-call-to-action, which clones its button
  // into shadow DOM — catch the retargeted click on the light-DOM wrapper.
  document.querySelector('.umd-brand-site-filter-actions').addEventListener('click', clearAll);

  pillsHost.addEventListener('click', function (e) {
    if (e.target.closest('[data-clear-all]')) { clearAll(); return; }
    var pill = e.target.closest('.umd-brand-site-filter-pill');
    if (!pill) return;
    var k = pill.getAttribute('data-k'), v = pill.getAttribute('data-v');
    if (k === 'q') {
      qInput.value = '';
    } else {
      form.querySelectorAll('input[data-group="' + k + '"]').forEach(function (cb) {
        if (cb.value === v) cb.checked = false;
      });
      syncBuckets();
    }
    update();
  });

  mobileToggle.addEventListener('click', function () {
    var open = form.toggleAttribute('data-open');
    mobileToggle.setAttribute('aria-expanded', open);
  });

  var param = new URLSearchParams(location.search).get('q');
  if (param) qInput.value = param;

  buildGroups();
  update();
})();
